import{_ as a,o as t,c as r,a0 as i}from"./chunks/framework.bcCluOOn.js";const u=JSON.parse('{"title":"AAYU Engine","description":"","frontmatter":{},"headers":[],"relativePath":"platform/engine.md","filePath":"platform/engine.md"}'),s={name:"platform/engine.md"};function n(o,e,l,h,d,p){return t(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="aayu-engine" tabindex="-1">AAYU Engine <a class="header-anchor" href="#aayu-engine" aria-label="Permalink to &quot;AAYU Engine&quot;">​</a></h1><p><strong>Status: Developer Preview</strong></p><p>The AAYU Engine is the core compiler and runtime that powers the entire ecosystem. It translates <code>.aayu</code> files into AAYU Intermediate Representation (IR), and then routes them to Target Generators.</p><h2 id="the-builder-api" tabindex="-1">The Builder API <a class="header-anchor" href="#the-builder-api" aria-label="Permalink to &quot;The Builder API&quot;">​</a></h2><p>The Builder API is the <strong>single point of truth</strong> for compilation. It orchestrates the pipeline and ensures that CLI, Chat, and VS Code Extensions all produce the exact same results.</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> builder.pipeline </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> build</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">build(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;main.aayu&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;generated_project&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="pipeline-stages" tabindex="-1">Pipeline Stages <a class="header-anchor" href="#pipeline-stages" aria-label="Permalink to &quot;Pipeline Stages&quot;">​</a></h2><h3 id="_1-lexer-parser" tabindex="-1">1. Lexer &amp; Parser <a class="header-anchor" href="#_1-lexer-parser" aria-label="Permalink to &quot;1. Lexer &amp; Parser&quot;">​</a></h3><p>Reads <code>.aayu</code> source code and builds the Abstract Syntax Tree (AST). It strictly enforces the AAYU grammar (<code>record</code>, <code>task</code>, <code>end.</code>).</p><h3 id="_2-ir-generator" tabindex="-1">2. IR Generator <a class="header-anchor" href="#_2-ir-generator" aria-label="Permalink to &quot;2. IR Generator&quot;">​</a></h3><p>Converts the AST into <strong>AAYU IR</strong> (a standardized JSON format). This abstracts away the syntax so that generators only care about <em>features</em> and <em>entities</em>.</p><h3 id="_3-target-scorer" tabindex="-1">3. Target Scorer <a class="header-anchor" href="#_3-target-scorer" aria-label="Permalink to &quot;3. Target Scorer&quot;">​</a></h3><p>Analyzes the IR and decides what technology stack to generate.</p><ul><li>e.g., If IR contains Database models, it triggers the <code>PostgresGenerator</code>.</li><li>e.g., If IR contains HTTP interactions, it triggers the <code>FastAPIGenerator</code>.</li></ul><h3 id="_4-generators" tabindex="-1">4. Generators <a class="header-anchor" href="#_4-generators" aria-label="Permalink to &quot;4. Generators&quot;">​</a></h3><p>The final stage of the Software Factory. It outputs raw, production-ready code into the output directory.</p><h2 id="experimental-runtime-vm" tabindex="-1">Experimental Runtime (VM) <a class="header-anchor" href="#experimental-runtime-vm" aria-label="Permalink to &quot;Experimental Runtime (VM)&quot;">​</a></h2><p>Parallel to the code generators, the AAYU Engine includes an experimental Stack-based Virtual Machine (VM) that executes <code>.aayu</code> bytecode (<code>.ayc</code>) directly for scripts that do not require full software generation.</p>`,18)])])}const g=a(s,[["render",n]]);export{u as __pageData,g as default};
